package com.fuelflex.platform.reception.entity; import java.time.OffsetDateTime; import java.util.UUID; import com.fuelflex.platform.reception.model.*; import com.fuelflex.platform.user.entity.User; import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter; @Entity @Table(name="reception_history",indexes=@Index(name="idx_reception_history_timeline",columnList="reception_id,performed_at,id")) @Getter @Setter @NoArgsConstructor public class ReceptionHistory { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="reception_id",nullable=false) private Reception reception; @Enumerated(EnumType.STRING) @Column(nullable=false,length=40) private ReceptionHistoryAction action; @Enumerated(EnumType.STRING) @Column(name="old_status",length=40) private ReceptionStatus oldStatus; @Enumerated(EnumType.STRING) @Column(name="new_status",nullable=false,length=40) private ReceptionStatus newStatus; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="performed_by",nullable=false) private User performedBy; @Column(nullable=false) private OffsetDateTime performedAt; @Column(length=1000) private String comment; @PrePersist void pre(){if(performedAt==null)performedAt=OffsetDateTime.now();} }
